<article class="card hero-card"><span class="eyebrow">Contest details</span><div class="section-head"><div><h2><?=e($contest['contest_title'])?></h2><p class="muted"><?=e($contest['description'])?></p></div><span class="badge badge-<?=e(strtolower($contest['lifecycle_status']))?>"><?=e($contest['lifecycle_status'])?></span></div>
<div class="detail-list"><div><small>Start time</small><strong><?=e($contest['start_time'])?></strong></div><div><small>End time</small><strong><?=e($contest['end_time'])?></strong></div><div><small>Duration</small><strong><?=e($contest['duration_minutes'])?> minutes</strong></div><div><small>Participants</small><strong><?=e($contest['participant_count'])?> registered</strong></div><div><small>Organized by</small><strong><?=e($contest['organizer_name'])?></strong></div><div><small>Registration deadline</small><strong><?=e($contest['registration_deadline'])?></strong></div></div>
<div class="actions contest-actions"><?php if(user()&&has_role('PARTICIPANT')):?><?php if($registered):?><form method="post" action="<?=e(url('/contests/'.$contest['contest_id'].'/cancel-registration'))?>" data-confirm="Cancel your registration?"><?=csrf_field()?><button class="button-outline">Cancel registration</button></form><?php elseif($contest['lifecycle_status']==='UPCOMING'):?><form method="post" action="<?=e(url('/contests/'.$contest['contest_id'].'/register'))?>"><?=csrf_field()?><button class="button">Register</button></form><?php endif;?><?php elseif(!user()):?><a class="button" href="<?=e(url('/login'))?>">Sign in to register</a><?php endif;?><a class="button-outline" href="<?=e(url('/contests/'.$contest['contest_id'].'/problems'))?>">View problems</a><a class="button-outline" href="<?=e(url('/leaderboard?contest='.$contest['contest_id']))?>">Leaderboard</a></div></article>
<section class="card"><div class="section-head"><h2>Problems</h2><span class="muted"><?=count($problems)?> available</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Problem</th><th>Difficulty</th><th>Limits</th><th></th></tr></thead><tbody><?php foreach($problems as $p):?><tr><td><strong><?=e($p['problem_code'])?></strong></td><td><?=e($p['problem_title'])?></td><td><span class="badge badge-<?=strtolower(e($p['difficulty']))?>"><?=e($p['difficulty'])?></span></td><td><?=e($p['time_limit_ms'])?> ms / <?=e($p['memory_limit_mb'])?> MB</td><td><a href="<?=e(url('/problems/'.$p['problem_id']))?>">Open →</a></td></tr><?php endforeach;?><?php if(!$problems):?><tr><td colspan="5" class="empty">Problems have not been published.</td></tr><?php endif;?></tbody></table></div></section>
